import type { PrintPagePlan } from './collagePrint';
export interface PdfRasterPage { jpeg: Blob; width: number; height: number }
/** Raster RGB PDF, not certified PDF/X. Page images must be generated by the verified print renderer. */
export function collagePdf(pages: readonly PdfRasterPage[], plan: PrintPagePlan): Blob {
 if (!pages.length || pages.length>200) throw new Error('Choose between 1 and 200 pages.');
 const parts: BlobPart[]=[];const offsets:number[]=[0];let length=0;
 const enc=new TextEncoder();
 const append=(value:string|Blob)=>{const part=typeof value==='string'?enc.encode(value):value;parts.push(part);length+=part instanceof Blob?part.size:part.byteLength;};
 const object=(id:number,body:string)=>{offsets[id]=length;append(id+' 0 obj\n'+body+'\nendobj\n');};
 const stream=(id:number,dict:string,data:Blob|string)=>{offsets[id]=length;const size=typeof data==='string'?enc.encode(data).byteLength:data.size;append(id+' 0 obj\n<< '+dict+' /Length '+size+' >>\nstream\n');append(data);append('\nendstream\nendobj\n');};
 const box=(values:number[])=>'['+values.map(v=>v.toFixed(5)).join(' ')+']';
 append('%PDF-1.4\n');
 object(1,'<< /Type /Catalog /Pages 2 0 R >>');
 object(2,'<< /Type /Pages /Count '+pages.length+' /Kids ['+pages.map((_,i)=>(3+i*3)+' 0 R').join(' ')+'] >>');
 pages.forEach((page,i)=>{
  if(page.jpeg.type!=='image/jpeg'||!page.jpeg.size||page.width!==plan.targetPixels.width||page.height!==plan.targetPixels.height)throw new Error('Print page dimensions or encoding do not match the print plan.');
  const id=3+i*3;
  object(id,'<< /Type /Page /Parent 2 0 R /MediaBox '+box(plan.mediaBoxPt)+' /BleedBox '+box(plan.mediaBoxPt)+' /TrimBox '+box(plan.trimBoxPt)+' /Resources << /XObject << /Im0 '+(id+1)+' 0 R >> >> /Contents '+(id+2)+' 0 R >>');
  stream(id+1,'/Type /XObject /Subtype /Image /Width '+page.width+' /Height '+page.height+' /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode',page.jpeg);
  stream(id+2,'','q\n'+plan.mediaBoxPt[2].toFixed(5)+' 0 0 '+plan.mediaBoxPt[3].toFixed(5)+' 0 0 cm\n/Im0 Do\nQ\n');
 });
 const xref=length;append('xref\n0 '+offsets.length+'\n0000000000 65535 f \n');
 for(let i=1;i<offsets.length;i++)append(String(offsets[i]).padStart(10,'0')+' 00000 n \n');
 append('trailer\n<< /Size '+offsets.length+' /Root 1 0 R >>\nstartxref\n'+xref+'\n%%EOF\n');
 return new Blob(parts,{type:'application/pdf'});
}
